			i++
		}
		if i >= len(s) {
			break
		}
		var p Pkg
		dec = json.NewDecoder(&sliceReader{&s, &i})
		if err := dec.Decode(&p); err != nil {
			break
		}
		m[p.ImportPath] = p.Export
	}
	return m
}

type sliceReader struct {
	s *string
	i *int
}

func (r *sliceReader) Read(p []byte) (int, error) {
	if *r.i >= len(*r.s) {
		return 0, io.EOF
	}
	n := copy(p, (*r.s)[*r.i:])
	*r.i += n
	return n, nil
}

