import sys, re, collections, os

rows = []
for line in open('/tmp/gen/list.tsv'):
    line = line.rstrip('\n')
    if not line: continue
    pkg, name, params = line.split('\t')
    params = params.split(', ') if params else []
    rows.append((pkg, name, params))

def is_exported(n):
    return n and n[0].isupper()

bypkg = collections.defaultdict(list)
for pkg, name, params in rows:
    m = re.match(r'^\(\*?([^\)]+)\)\.(\w+)$', name)
    if m:
        recv, meth = m.groups()
        star = name.startswith('(*')
        if not is_exported(recv.split('.')[-1]) or not is_exported(meth):
            continue
        bypkg[pkg].append(('m', star, recv, meth, params))
    else:
        if not is_exported(name.split('.')[-1]):
            continue
        bypkg[pkg].append(('f', '', '', name, params))

# collect all package paths used in type strings
paths = set()
for pkg, name, params in rows:
    for p in params:
        paths.update(re.findall(r'(?:^|[^a-zA-Z0-9_])([a-zA-Z0-9_/]+(?:/[a-zA-Z0-9_/]+)*)\.[A-Z]\w*', p))
        paths.update(re.findall(r'(?:^|[^a-zA-Z0-9_])([a-zA-Z0-9_/]+(?:/[a-zA-Z0-9_/]+)*)\.[a-z]\w*', p))
allpaths = sorted(paths, key=lambda s: (-len(s), s))
alias = {}
for i, p in enumerate(allpaths):
    alias[p] = 'ip%d' % i

def conv(t):
    for p in allpaths:
        t = re.sub(r'(?<![a-zA-Z0-9_/])' + re.escape(p) + r'\.', alias[p] + '.', t)
    return t

def unexported_param(params):
    for p in params:
        # any qualified name with lowercase last segment that is a type
        for m in re.finditer(r'(?<![a-zA-Z0-9_/])([a-zA-Z0-9_/]+)\.(\w+)', p):
            path, nm = m.group(1), m.group(2)
            if not nm[0].isupper():
                return True
    return False

os.makedirs('/tmp/probe', exist_ok=True)
for f in os.listdir('/tmp/probe'):
    os.remove(os.path.join('/tmp/probe', f))

idx = 0
skipped = []
for pkg in sorted(bypkg):
    entries = bypkg[pkg]
    imports = sorted({alias[pp] for pp in allpaths if pp in pkg or any(pp in p for p in [pp for e in entries for pp in e[4]])})
    # always import the package itself
    lines = ['package probe%d' % idx, '', 'import (']
    imp_alias = {}
    seen = {}
    for pp in sorted(allpaths):
        if not any(pp in pp2 for pp2 in [pkg] + [p for e in entries for p in e[4]]):
            continue
        a = alias[pp]
        lines.append('\t%s "%s"' % (a, pp))
        imp_alias[pp] = a
    lines.append(')')
    lines.append('')
    lines.append('func z[T any]() T { var v T; return v }')
    lines.append('')
    lines.append('func call() {')
    n = 0
    for kind, star, recv, name, params in entries:
        if unexported_param(params):
            skipped.append((pkg, name, 'unexported param'))
            continue
        args = ', '.join('z[%s]()' % conv(p) for p in params)
        if kind == 'f':
            lines.append('\t%s(%s)' % (name, args))
        else:
            if star:
                lines.append('\tr := z[%s]()' % conv(recv))
                lines.append('\tr.%s(%s)' % (name, args))
            else:
                lines.append('\tr := z[%s]()' % conv(recv))
                lines.append('\tr.%s(%s)' % (name, args))
        n += 1
    lines.append('\t_ = z[int]()')
    lines.append('}')
    d = '/tmp/probe/p%d' % idx
    os.makedirs(d, exist_ok=True)
    open(d + '/f.go', 'w').write('\n'.join(lines) + '\n')
    open(d + '/name.txt', 'w').write(pkg + '\n')
    idx += 1
print("dirs:", idx, "skipped:", len(skipped))
for s in skipped[:20]: print(s)
open('/tmp/gen/skipped.txt','w').write('\n'.join('%s\t%s\t%s' % s for s in skipped))
open('/tmp/gen/alias.txt','w').write('\n'.join('%s\t%s' % (v,k) for k,v in alias.items()))
