for line in open('/tmp/gen/alias.txt'):
    a, pp = line.rstrip('\n').split('\t')
    alias[a] = pp
def back(t):
    return re.sub(r'(ip\d+)\.', lambda mm: alias.get(mm.group(1), mm.group(1))+'.', t)
reported = set()
for line in open('all.out'):
    line = line.rstrip('\n')
    if not line: continue
    pos, expr = line.split('\t', 1)
    reported.add(pos.rstrip(':'))
