    pkg = open(os.path.join(d,'name.txt')).read().strip()
    raws = open(os.path.join(d,'f.go')).read().split('\n')
    var2type = {}
    for i, raw in enumerate(raws, 1):
        l = raw.strip()
        m = re.match(r'^(r\d+) := z\[(.+)\]\(\)$', l)
        if m: var2type[m.group(1)] = m.group(2)
        if not (re.match(r'^(ip\d+)\.\w+\(', l) or re.match(r'^(r\d+)\.\w+\(', l)): continue
        lead = len(raw) - len(raw.lstrip())
        pos = '%s/f.go:%d:%d' % (d, i, lead + 1 + raw.lstrip().index('('))
        if pos in reported: continue
        cm = re.match(r'^(ip\d+)\.(\w+)\(', l)
        cm2 = re.match(r'^(r\d+)\.(\w+)\(', l)
        if cm: out.append(pkg + '\t' + alias.get(cm.group(1), cm.group(1)) + '.' + cm.group(2))
        else: out.append(pkg + '\t' + '(%s).%s' % (back(var2type.get(cm2.group(1), '?')), cm2.group(2)))
