	for pkg, list := range byPkg {
		used := map[string]bool{alias[pkg]: true}
		var body []string
		n := 0
		for _, idx := range list {
			e := entries[idx]
			p0 := e.params[0]
			if e.variadic {
				if sl, ok := p0.(*types.Slice); ok {
					p0 = sl.Elem()
				}
			}
			rest := ""
			for _, p := range e.params[1:] {
				if e.variadic && p == e.params[len(e.params)-1] {
					rest += ", z[...]" 
				}
			}
			for _, c := range candidates {
				if c.typ == nil {
					switch p0.(type) {
					case *types.Pointer, *types.Interface, *types.Signature, *types.Slice, *types.Map, *types.Chan:
					default:
						continue
					}
				} else if !types.AssignableTo(c.typ, p0) {
					continue
				}
				// build full arg list
				var args []string
				if e.variadic && len(e.params) == 1 {
					args = append(args, c.expr)
				} else if e.variadic && len(e.params) > 1 {
					args = append(args, c.expr)
					for _, p := range e.params[1 : len(e.params)-1] {
						args = append(args, "z["+conv(p.String())+"]()")
					}
				} else {
					args = append(args, c.expr)
					for _, p := range e.params[1:] {
						args = append(args, "z["+conv(p.String())+"]()")
					}
				}
				var callee string
				var label string
				if e.kind == "func" {
					callee = alias[pkg] + "." + e.name
					label = pkg + "." + e.name
				} else {
					rn := fmt.Sprintf("r%d", n)
					body = append(body, fmt.Sprintf("\\t%s := z[%s]()", rn, conv(strings.TrimPrefix(e.recv, "*"))))
					callee = rn + "." + e.name
					label = "(" + e.recv + ")." + e.name
				}
				body = append(body, fmt.Sprintf("\\t%s(%s)", callee, strings.Join(args, ", ")))
				used[alias[pkg]] = true
				// record the needed packages from args
				for _, a := range args {
					for _, m := range rePaths.FindAllStringSubmatch(a, -1) {
						if alias[m[2]] != "" {
							used[alias[m[2]]] = true
						}
					}
				}
				for _, p := range e.params[1:] {
					for _, m := range rePaths.FindAllStringSubmatch(p.String(), -1) {
						if alias[m[2]] != "" {
							used[alias[m[2]]] = true
						}
					}
				}
				if e.kind == "method" {
					for _, m := range rePaths.FindAllStringSubmatch(e.recv, -1) {
						if alias[m[2]] != "" {
							used[alias[m[2]]] = true
						}
					}
				}
				used[alias[pkg]] = true
				linesOut = append(linesOut, label+"\\t"+c.kind)
				n++
			}
		}
		// build file
		var lines []string
		aliasList := []string{}
		for a := range used {
			aliasList = append(aliasList, a)
		}
		sort.Strings(aliasList)
		lines = append(lines, "package probe2")
		lines = append(lines, "")
		lines = append(lines, "import (")
		for _, a := range aliasList {
			pp := aliasrev(a)
			if strings.HasPrefix(pp, "vendor/") {
				pp = pp[len("vendor/"):]
			}
			lines = append(lines, fmt.Sprintf("\\t%s \\"%s\\"", a, pp))
		}
		lines = append(lines, ")")
		lines = append(lines, "")
		lines = append(lines, "func z[T any]() T { var v T; return v }")
		lines = append(lines, "")
		lines = append(lines, "func call() {")
		lines = append(lines, body...)
		lines = append(lines, "\\t_ = z[int]()")
		lines = append(lines, "}")
		d := "/tmp/probe2/" + strings.ReplaceAll(pkg, "/", "_")
		os.MkdirAll(d, 0755)
		os.WriteFile(d+"/f.go", []byte(strings.Join(lines, "\\n")+"\\n"), 0644)
		os.WriteFile(d+"/name.txt", []byte(pkg+"\\n"), 0644)
	}
	for _, l := range linesOut {
		fmt.Println(l)
	}
	_ = filepath.Base
}

func aliasrev(a string) string {
	for k, v := range alias {
		if v == a {
			return k
		}
	}
	return ""
}

