		if n.Obj().Pkg() == nil && n.Obj().Name() == "error" {
			return true
		}
		return types.Implements(n, errIface)
	}
	if p, ok := t.(*types.Pointer); ok {
		return types.Implements(p, errIface)
	}
	return false
}

type Pkg struct {
	ImportPath string
	Export     string
}

func exportFiles(paths ...string) map[string]string {
	args := append([]string{"list", "-export", "-json"}, paths...)
	out, err := exec.Command("go", args...).CombinedOutput()
	if err != nil {
		fmt.Fprintln(os.Stderr, "list err:", err, string(out))
		return nil
	}
	m := map[string]string{}
	dec := json.NewDecoder(strings.NewReader(string(out)))
	for {
		var p Pkg
		if err := dec.Decode(&p); err != nil {
			break
		}
		m[p.ImportPath] = p.Export
	}
	return m
}

type entry struct {
	pkg      string
	name     string
	kind     string // func/method
	recvT    types.Type
	params   []types.Type
	variadic bool
}

var alias = map[string]string{}
var aliasRev = map[string]string{}
var rePaths = regexp.MustCompile(`(^|[^a-zA-Z0-9_/])([a-zA-Z0-9_/]+)\.[A-Za-z]\w*`)

func main() {
	out, err := exec.Command("go", "list", "std").CombinedOutput()
	if err != nil {
		fmt.Fprintln(os.Stderr, "list std err:", err)
		return
	}
	var paths []string
	for _, l := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		l = strings.TrimSpace(l)
		if l == "" || strings.Contains(l, "/internal/") || strings.HasPrefix(l, "internal/") {
			continue
		}
		if strings.HasSuffix(l, "/v2") || strings.HasSuffix(l, "/v3") {
			continue
		}
		paths = append(paths, l)
	}
	fset := token.NewFileSet()
	files := exportFiles(paths...)
	imp := importer.ForCompiler(fset, "gc", func(path string) (io.ReadCloser, error) {
		f, ok := files[path]
		if !ok {
			return nil, fmt.Errorf("no export file for %s", path)
		}
		return os.Open(f)
	})
	bytesPkg, _ := imp.Import("bytes")
	stringsPkg, _ := imp.Import("strings")
	ioPkg, _ := imp.Import("io")
	osPkg, _ := imp.Import("os")
	candidates := []struct {
		kind string
		expr string
		typ  types.Type
	}{
		{"bytesbuf", "&cbuf", types.NewPointer(bytesPkg.Scope().Lookup("Buffer").Type())},
		{"stdout", "os.Stdout", types.NewPointer(osPkg.Scope().Lookup("File").Type())},
		{"stderr", "os.Stderr", types.NewPointer(osPkg.Scope().Lookup("File").Type())},
		{"stringsb", "&csb", types.NewPointer(stringsPkg.Scope().Lookup("Builder").Type())},
		{"iowriter", "cw", ioPkg.Scope().Lookup("Writer").Type()},
		{"ioreader", "cr", ioPkg.Scope().Lookup("Reader").Type()},
		{"error", "cerr", errType},
		{"nil", "nil", nil},
	}
	var entries []entry
	needed := map[string]bool{}
	needed["bytes"] = true
	needed["strings"] = true
	needed["io"] = true
	needed["os"] = true
	for _, path := range paths {
		pkg, err := imp.Import(path)
		if err != nil {
			continue
		}
		needed[path] = true
		scope := pkg.Scope()
		for _, name := range scope.Names() {
			obj := scope.Lookup(name)
			switch o := obj.(type) {
			case *types.Func:
				sig := o.Type().(*types.Signature)
				if !anyError(sig) {
					continue
				}
				var ps []types.Type
				for i := 0; i < sig.Params().Len(); i++ {
					ps = append(ps, sig.Params().At(i).Type())
				}
				entries = append(entries, entry{pkg: path, name: name, kind: "func", params: ps, variadic: sig.Variadic()})
			case *types.TypeName:
				if o.IsAlias() {
					continue
				}
				n, ok := o.Type().(*types.Named)
				if !ok {
					continue
				}
				var ms *types.MethodSet
				if _, isIface := n.Underlying().(*types.Interface); isIface {
					ms = types.NewMethodSet(n)
				} else {
					if n.TypeParams() != nil && n.TypeParams().Len() > 0 {
						continue
					}
					ms = types.NewMethodSet(types.NewPointer(n))
				}
				seen := map[string]bool{}
				for i := 0; i < ms.Len(); i++ {
					sel := ms.At(i)
					f, ok := sel.Obj().(*types.Func)
					if !ok || seen[f.Name()] {
						continue
					}
					seen[f.Name()] = true
					sig := f.Type().(*types.Signature)
					if !anyError(sig) {
						continue
					}
					var ps []types.Type
					for j := 0; j < sig.Params().Len(); j++ {
						ps = append(ps, sig.Params().At(j).Type())
					}
					recvT := types.Type(n)
					if _, isPtr := sel.Recv().(*types.Pointer); isPtr {
						recvT = types.NewPointer(n)
					}
					entries = append(entries, entry{pkg: path, name: f.Name(), kind: "method", recvT: recvT, params: ps, variadic: sig.Variadic()})
				}
			}
		}
	}
	// collect needed packages from type strings
	for _, e := range entries {
		if e.recvT != nil {
			collectNeeded(e.recvT.String(), needed)
		}
		for _, p := range e.params {
			collectNeeded(p.String(), needed)
		}
	}
	var allPaths []string
	for p := range needed {
		allPaths = append(allPaths, p)
	}
	sort.Slice(allPaths, func(i, j int) bool { return len(allPaths[i]) > len(allPaths[j]) })
	for i, p := range allPaths {
		alias[p] = fmt.Sprintf("ip%d", i)
		aliasRev[fmt.Sprintf("ip%d", i)] = p
	}
	conv := func(t string) string {
		for _, p := range allPaths {
			t = strings.ReplaceAll(t, p+".", alias[p]+".")
		}
		return t
	}
	q := func(p *types.Package) string {
		if p == nil {
			return ""
		}
		return alias[p.Path()]
	}
	tstr := func(t types.Type) string {
		if t == nil {
			return ""
		}
		return types.TypeString(t, q)
	}

	os.RemoveAll("/tmp/probe2")
	os.MkdirAll("/tmp/probe2", 0755)
	byPkg := map[string][]int{}
	var labels []string
	for idx, e := range entries {
		if e.kind == "method" {
			last := e.recvT.String()
			last = strings.TrimPrefix(last, "*")
			last = last[strings.LastIndex(last, ".")+1:]
			if len(last) > 0 && last[0] >= 'a' && last[0] <= 'z' {
				continue
			}
			last = last[strings.LastIndex(last, ".")+1:]
		} else {
			ln := e.name
			if len(ln) > 0 && ln[0] >= 'a' && ln[0] <= 'z' {
				continue
			}
		}
		if len(e.params) == 0 {
			continue
		}
		byPkg[e.pkg] = append(byPkg[e.pkg], idx)
	}
	n := 0
	for pkg, list := range byPkg {
		used := map[string]bool{}
		var body []string
		k := 0
		for _, idx := range list {
			e := entries[idx]
			p0 := e.params[0]
			if e.variadic {
				if sl, ok := p0.(*types.Slice); ok {
					p0 = sl.Elem()
				}
			}
			var label string
			if e.kind == "func" {
				label = pkg + "." + e.name
			} else {
				label = "(" + tstr(e.recvT) + ")." + e.name
			}
			for _, c := range candidates {
				if c.typ == nil {
					switch p0.(type) {
					case *types.Pointer, *types.Interface, *types.Signature, *types.Slice, *types.Map, *types.Chan:
					default:
						continue
					}
				} else if !types.AssignableTo(c.typ, p0) {
					continue
				}
				var args []string
				args = append(args, c.expr)
				for i, p := range e.params {
					if e.variadic && i == 0 {
						continue
					}
					if e.variadic && i == len(e.params)-1 {
						continue
					}
					args = append(args, "z["+tstr(p)+"]()")
				}
				var callee string
				if e.kind == "func" {
					callee = alias[pkg] + "." + e.name
				} else {
					rn := fmt.Sprintf("r%d", k)
					body = append(body, fmt.Sprintf("\t%s := z[%s]()", rn, tstr(e.recvT)))
					callee = rn + "." + e.name
				}
				body = append(body, fmt.Sprintf("\t%s(%s)", callee, strings.Join(args, ", ")))
				used[alias[pkg]] = true
				for _, a := range args {
					for _, m := range rePaths.FindAllStringSubmatch(a, -1) {
						if v, ok := alias[m[2]]; ok && v != "" {
							used[v] = true
						}
					}
				}
				for _, p := range e.params {
					for _, m := range rePaths.FindAllStringSubmatch(tstr(p), -1) {
						if v, ok := alias[m[2]]; ok && v != "" {
							used[v] = true
						}
					}
				}
				if e.recvT != nil {
					for _, m := range rePaths.FindAllStringSubmatch(tstr(e.recvT), -1) {
						if v, ok := alias[m[2]]; ok && v != "" {
							used[v] = true
						}
					}
				}
				labels = append(labels, label+"\t"+c.kind)
				k++
			}
			_ = conv
			_ = n
		}
		var lines []string
		var aliasList []string
		for a := range used {
			aliasList = append(aliasList, a)
		}
		sort.Strings(aliasList)
		lines = append(lines, "package probe2")
		lines = append(lines, "")
		lines = append(lines, "import (")
		for _, a := range aliasList {
			pp := aliasRev[a]
			if strings.HasPrefix(pp, "vendor/") {
				pp = pp[len("vendor/"):]
			}
			lines = append(lines, fmt.Sprintf("\t%s \"%s\"", a, pp))
		}
		lines = append(lines, ")")
		lines = append(lines, "")
		lines = append(lines, "func z[T any]() T { var v T; return v }")
		lines = append(lines, "")
		if used[alias["bytes"]] {
			lines = append(lines, "var cbuf bytes.Buffer")
			lines = append(lines, "")
		}
		if used[alias["strings"]] {
			lines = append(lines, "var csb strings.Builder")
			lines = append(lines, "")
		}
		if used[alias["io"]] {
			lines = append(lines, "var cw io.Writer")
			lines = append(lines, "var cr io.Reader")
			lines = append(lines, "")
		}
		lines = append(lines, "var cerr error")
		lines = append(lines, "")
		lines = append(lines, "func call() {")
		lines = append(lines, body...)
		lines = append(lines, "\t_ = z[int]()")
		lines = append(lines, "}")
		d := "/tmp/probe2/" + strings.ReplaceAll(pkg, "/", "_")
		os.MkdirAll(d, 0755)
		os.WriteFile(d+"/f.go", []byte(strings.Join(lines, "\n")+"\n"), 0644)
		os.WriteFile(d+"/name.txt", []byte(pkg+"\n"), 0644)
	}
	for _, l := range labels {
		fmt.Println(l)
	}
}

func collectNeeded(s string, needed map[string]bool) {
	for _, m := range rePaths.FindAllStringSubmatch(s, -1) {
		needed[m[2]] = true
	}
}

func anyError(sig *types.Signature) bool {
	if sig.Results() == nil {
		return false
	}
	for i := 0; i < sig.Results().Len(); i++ {
		if isError(sig.Results().At(i).Type()) {
			return true
		}
	}
	return false
}
EOF
