					for j := 0; j < sig.Params().Len(); j++ {
						ps = append(ps, sig.Params().At(j).Type())
					}
					recvT := types.Type(nt)
					if _, isPtr := ms.At(i).Recv().(*types.Pointer); isPtr {
						recvT = types.NewPointer(nt)
					}
					entries = append(entries, entry{pkg: path, name: f.Name(), kind: "method", recvT: recvT, params: ps, variadic: sig.Variadic()})
				}
			}
		}
	}
	for _, e := range entries {
		needed[e.pkg] = true
		if e.recvT != nil {
			collect(tstr(e.recvT), needed)
		}
		for _, p := range e.params {
			collect(tstr(p), needed)
		}
	}
	needed["bytes"] = true
	needed["strings"] = true
	needed["io"] = true
	needed["os"] = true
	var allPaths []string
	for p := range needed {
		allPaths = append(allPaths, p)
	}
	sort.Slice(allPaths, func(i, j int) bool { return len(allPaths[i]) > len(allPaths[j]) })
	for i, p := range allPaths {
		alias[p] = fmt.Sprintf("ip%d", i)
		aliasRev[fmt.Sprintf("ip%d", i)] = p
	}
	for _, e := range entries {
		if e.kind == "func" {
			last := e.name
			if len(last) > 0 && last[0] >= 'a' && last[0] <= 'z' {
				continue
			}
		} else {
			s := strings.TrimPrefix(tstr(e.recvT), "*")
			last := s[strings.LastIndex(s, ".")+1:]
			if len(last) > 0 && last[0] >= 'a' && last[0] <= 'z' {
				continue
			}
		}
		if len(e.params) == 0 {
			continue
		}
		p0 := e.params[0]
		if e.variadic {
			if sl, ok := p0.(*types.Slice); ok {
				p0 = sl.Elem()
			}
		}
		var label string
		if e.kind == "func" {
			label = e.pkg + "." + e.name
		} else {
			label = "(" + tstr(e.recvT) + ")." + e.name
		}
		for _, c := range cands {
			if c.typ == nil {
				switch p0.(type) {
				case *types.Pointer, *types.Interface, *types.Signature, *types.Slice, *types.Map, *types.Chan:
				default:
					continue
				}
			} else if !types.AssignableTo(c.typ, p0) {
				continue
			}
			args := []string{c.expr}
			for i, p := range e.params {
				if i == 0 {
					continue
				}
				if e.variadic && i == len(e.params)-1 {
					continue
				}
				args = append(args, "z["+tstr(p)+"]()")
			}
			recv := ""
			if e.kind == "method" {
				recv = tstr(e.recvT)
			}
			fmt.Printf("%s\t%s\t%s\t%s\t%s\n", label, e.kind, c.expr, recv, strings.Join(args[1:], " Â§ "))
		}
	}
}

func tstr(t types.Type) string {
	if t == nil {
		return ""
	}
	return types.TypeString(t, func(p *types.Package) string {
		if p == nil {
			return ""
		}
		if a, ok := alias[p.Path()]; ok {
			return a
		}
		return p.Path()
	})
}

func exportFiles(paths []string) map[string]string {
	args := append([]string{"list", "-export", "-json"}, paths...)
	out, err := exec.Command("go", args...).CombinedOutput()
	if err != nil {
		fmt.Fprintln(os.Stderr, "list err:", err, string(out))
		return nil
	}
	m := map[string]string{}
	d := json.NewDecoder(strings.NewReader(string(out)))
	for {
		var p Pkg
		if err := d.Decode(&p); err != nil {
			break
		}
		m[p.ImportPath] = p.Export
	}
	return m
}
