package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
)

const src = `package p
type T struct{}
type TA = T
var x = &TA{}
var y = &T{}
func f() TA { return T{} }
func g() (a TA) { return }
`

func main() {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "p.go", src, 0)
	if err != nil {
		fmt.Println("parse err:", err)
		return
	}
	info := &types.Info{Types: map[ast.Expr]types.TypeAndValue{}, Defs: map[*ast.Ident]types.Object{}, Uses: map[*ast.Ident]types.Object{}}
	conf := types.Config{}
	_, err = conf.Check("p", fset, []*ast.File{file}, info)
	if err != nil {
		fmt.Println("check err:", err)
		return
	}
	ast.Inspect(file, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.UnaryExpr:
			t := info.TypeOf(n)
			fmt.Printf("unary %s -> %s (%T)\n", exprString(n), t, t)
		case *ast.CompositeLit:
			t := info.TypeOf(n)
			fmt.Printf("composite %s -> %s (%T)\n", exprString(n), t, t)
		case *ast.FuncDecl:
			if n.Type.Results != nil {
				for _, r := range n.Type.Results.List {
					t := info.TypeOf(r.Type)
					fmt.Printf("func %s result %s -> %s (%T)\n", n.Name.Name, exprString(r.Type), t, t)
				}
			}
		}
		return true
	})
}

func exprString(e ast.Expr) string {
	switch e := e.(type) {
	case *ast.UnaryExpr:
		return e.Op.String() + exprString(e.X)
	case *ast.CompositeLit:
		return exprString(e.Type) + "{}"
	case *ast.Ident:
		return e.Name
	case *ast.SelectorExpr:
		return exprString(e.X) + "." + e.Sel.Name
	}
	return "?"
}
EOF
gofmt -w p4.go && go build -o probe4 . && ./probe4"}

