package main

import (
	"fmt"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"strings"
	"io"
)

const src = `package p
import "nonexistent/pkg"
var _ = pkg.X
`

func main() {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "p.go", src, 0)
	if err != nil {
		fmt.Println("parse err:", err)
	}
	imp := importer.ForCompiler(fset, "gc", func(path string) (io.ReadCloser, error) {
		return io.NopCloser(strings.NewReader("")), nil
	})
	conf := types.Config{Importer: imp}
	_, terr := conf.Check("p", fset, []*ast.File{file}, nil)
	fmt.Println("err:", terr)
	_ = types
}
EOF
sed -i 's|"go/parser"|"go/ast"\n\t"go/parser"|' p6.go && gofmt -w p6.go && go build -o p6 . 2>&1|head -3 && ./p6"}

