// tagList implements flag.Value for the -tags flag.
type tagList []string

func (t tagList) String() string {
	if t == nil {
		return ""
	}
	return strings.Join(t, " ")
}

func (t *tagList) Set(value string) error {
	if value == "" {
		return nil
	}
	for _, field := range strings.FieldsFunc(value, func(r rune) bool {
		return r == ',' || r == ' '
	}) {
		*t = append(*t, field)
	}
	return nil
}

// stringsSplit splits s on sep and drops empty entries.
func stringsSplit(s, sep string) []string {
	var out []string
	for _, part := range strings.Split(s, sep) {
		if part == "" {
			continue
		}
		out = append(out, part)
	}
	return out
}

