// for that function. An empty filter list means all calls are excluded.
type excludeMap map[string][]string

// loadExcludeFile reads the exclude list from the given path.
func loadExcludeFile(path string) (excludeMap, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("Could not read exclude file: %v", err)
	}
	m := excludeMap{}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSuffix(line, "\r")
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		name, typ := parseExcludedSymbol(line)
