package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/scanner"
	"go/token"
	"go/types"
	"io"
	"os"
	"os/exec"
	"strings"
)

// Error is an error associated with a package, in the same form as the one
// produced by the go/packages loader.
type Error struct {
	Pos string
	Msg string
}

func (e Error) Error() string {
	if e.Pos == "" {
		return e.Msg
	}
	return e.Pos + ": " + e.Msg
}

// Package is a loaded Go package.
type Package struct {
	ID        string
	PkgPath   string
	Name      string
	Dir       string
	GoFiles   []string
	Errors    []Error
	Types     *types.Package
	TypesInfo *types.Info
	Syntax    []*ast.File
	Sources   map[string][]byte
	ImportMap map[string]string
	Export    string
	DepOnly   bool
}

// Config holds the options for loading packages.
type Config struct {
	Tests      bool
	BuildFlags []string
	Mod        string
}

type listPackage struct {
	ImportPath string
	Name       string
	Dir        string
	GoFiles    []string
	DepOnly    bool
	ForTest    string
	Export     string
	ImportMap  map[string]string
	Imports    []string
	Std        bool
	Error      *struct {
		ImportStack []string
		Pos         string
		Err         string
	}
}

// Load resolves the given patterns to packages and returns the root packages.
