type loader struct {
	fset   *token.FileSet
	cfg    *Config
	pkgs   []*Package
	byID   map[string]*Package
	byPath map[string]*Package
	byDir  map[string]*Package
	order  []*Package
	gcImp  types.Importer
	checked map[string]bool
	busy    map[string]bool
}

func (ld *loader) parseJSON(data string) error {
	ld.gcImp = importer.ForCompiler(ld.fset, "gc", func(path string) (io.ReadCloser, error) {
		p, ok := ld.byPath[path]
		if !ok || p.Export == "" {
			return nil, fmt.Errorf("no export data for %s", path)
		}
		return os.Open(p.Export)
	})
	dec := json.NewDecoder(strings.NewReader(data))
	for {
		var lp listPackage
		if err := dec.Decode(&lp); err != nil {
			if err == io.EOF {
				break
			}
			return err
		}
		p := &Package{
			ID:        lp.ImportPath,
			PkgPath:   stripTestSuffix(lp.ImportPath),
			Name:      lp.Name,
			Dir:       lp.Dir,
			GoFiles:   absPaths(lp.Dir, lp.GoFiles),
			ImportMap: lp.ImportMap,
			Export:    lp.Export,
			DepOnly:   lp.DepOnly,
		}
		if lp.Error != nil {
			pos := lp.Error.Pos
			if pos == "" {
				pos = "-"
			}
			p.Errors = append(p.Errors, Error{Pos: pos, Msg: strings.TrimSpace(lp.Error.Err)})
		}
		ld.pkgs = append(ld.pkgs, p)
		ld.order = append(ld.order, p)
		if _, ok := ld.byID[p.ID]; !ok {
			ld.byID[p.ID] = p
		}
		if _, ok := ld.byPath[p.PkgPath]; !ok {
			ld.byPath[p.PkgPath] = p
		}
		if p.Dir != "" {
			if _, ok := ld.byDir[p.Dir]; !ok {
				ld.byDir[p.Dir] = p
			}
		}
	}
	return nil
}

func stripTestSuffix(id string) string {
	if i := strings.Index(id, " ["); i >= 0 {
		return id[:i]
	}
	return id
}

func absPaths(dir string, files []string) []string {
	var out []string
	for _, f := range files {
		if filepath.IsAbs(f) {
			out = append(out, f)
			continue
		}
		out = append(out, filepath.Join(dir, f))
	}
	return out
}

// imp is the importer used while type checking a package. It resolves imports
// relative to the package being checked and falls back to loading the
// dependency from source when no export data is available.
type imp struct {
	ld   *loader
	from *Package
}

func (i *imp) Import(path string) (*types.Package, error) {
	return i.ImportFrom(path, i.from.Dir, 0)
}

func (i *imp) ImportFrom(path, dir string, mode types.ImportMode) (*types.Package, error) {
	if from := i.ld.byDir[dir]; from != nil {
		i.from = from
	}
	resolved := path
	if i.from != nil && i.from.ImportMap != nil {
		if r, ok := i.from.ImportMap[path]; ok {
			resolved = r
		}
	}
	target, ok := i.ld.byID[resolved]
	if !ok {
		target, ok = i.ld.byPath[resolved]
	}
	if !ok {
		return types.NewPackage(resolved, ""), nil
	}
	if target.Types != nil {
		return target.Types, nil
	}
	if target.Export != "" {
		return i.ld.gcImp.Import(resolved)
	}
	if err := i.ld.load(target); err != nil {
		return nil, err
	}
	if target.Types != nil {
		return target.Types, nil
	}
	return types.NewPackage(resolved, ""), nil
}

// load parses and type checks the package, recording any errors.
func (ld *loader) load(p *Package) error {
	if p.loaded {
		return nil
	}
	p.loaded = true
	if ld.busy[p.ID] {
		return nil
	}
	ld.busy[p.ID] = true
	defer func() { ld.busy[p.ID] = false }()

	info := &types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
		Implicits:  map[ast.Node]types.Object{},
		Instances:  map[*ast.Ident]types.Instance{},
		Scopes:     map[ast.Node]*types.Scope{},
	}
	p.TypesInfo = info
	p.Sources = map[string][]byte{}
	var files []*ast.File
	var parseErrs []Error
	for _, f := range p.GoFiles {
		data, err := os.ReadFile(f)
		if err != nil {
			parseErrs = append(parseErrs, Error{Pos: f + ":1", Msg: err.Error()})
			continue
		}
		p.Sources[f] = data
		file, err := parser.ParseFile(ld.fset, f, data, parser.ParseComments)
		if err != nil {
			if el, ok := err.(scanner.ErrorList); ok {
				for _, e := range el {
					parseErrs = append(parseErrs, Error{Pos: e.Pos.String(), Msg: e.Msg})
				}
			} else {
				parseErrs = append(parseErrs, Error{Pos: f, Msg: err.Error()})
			}
		}
		if file != nil {
			files = append(files, file)
		}
	}
	p.Syntax = files
	p.Errors = append(p.Errors, parseErrs...)

	conf := types.Config{
		Importer: &imp{ld: ld, from: p},
		Error: func(err error) {
			if te, ok := err.(types.Error); ok {
				msg := te.Msg
				if i := strings.LastIndex(msg, " declared and not used"); i >= 0 {
					msg = "declared and not used: " + msg[:i]
				}
				p.Errors = append(p.Errors, Error{Pos: te.Fset.Position(te.Pos).String(), Msg: msg})
			}
		},
	}
	pkg, _ := conf.Check(p.PkgPath, ld.fset, files, info)
	p.Types = pkg
	return nil
}
