{"command": "cd /tmp/impl && cat > checker.go <<'GOEOF'
package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

// reportedError is a single unchecked error found by the checker.
type reportedError struct {
	file string
	line int
	col  int
	text string
	fn   string
}

// Checker checks Go packages for silently ignored errors.
type Checker struct {
	Abspath         bool
	Asserts         bool
	Blank           bool
	Excludes        excludeMap
	Ignore          ignoreList
	IgnoreGenerated bool
	IgnoreTests     bool
	Log             *log.Logger
	Mod             string
	Tags            tagList
	Verbose         bool

	fset   *token.FileSet
	Errors []reportedError
	seen   map[string]bool
	cwd    string
}

var generatedRe = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

// Check loads the packages matching the given patterns and checks them.
func (c *Checker) Check(patterns []string) error {
	c.cwd, _ = os.Getwd()
	cfg := &Config{
		Tests:      !c.IgnoreTests,
		BuildFlags: buildFlags(c.Tags),
		Mod:        c.Mod,
	}
	pkgs, err := Load(cfg, patterns...)
	if err != nil {
		return err
	}
	c.seen = map[string]bool{}
	c.fset = token.NewFileSet()
	for _, pkg := range pkgs {
		if err := c.load(pkg); err != nil {
			return err
		}
	}
	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			return fmt.Errorf("errors while loading package %s: %v", pkg.ID, pkg.Errors)
		}
	}
	for _, pkg := range pkgs {
		if c.Verbose {
			c.Log.Printf("checking %s", pkg.PkgPath)
		}
		c.checkPackage(pkg)
	}
	return nil
}

func buildFlags(tags tagList) []string {
	if len(tags) == 0 {
		return nil
	}
	return []string{"-tags=" + strings.Join(tags, ",")}
}

// load parses and type checks a package, if that has not happened yet.
func (c *Checker) load(p *Package) error {
	c.fset = p.fset()
	return loadPackage(p)
}

// checkPackage walks the package's files and reports ignored errors.
func (c *Checker) checkPackage(p *Package) {
	info := p.TypesInfo
	for _, file := range p.Syntax {
		if c.IgnoreGenerated && isGeneratedFile(file) {
			continue
		}
		ast.Inspect(file, func(n ast.Node) bool {
			switch node := n.(type) {
			case *ast.ExprStmt:
				if call, ok := node.X.(*ast.CallExpr); ok {
					c.checkCall(call, info, p)
				}
			case *ast.GoStmt:
				if call, ok := node.Call.(*ast.CallExpr); ok {
					c.checkCall(call, info, p)
				}
			case *ast.DeferStmt:
				if call, ok := node.Call.(*ast.CallExpr); ok {
					c.checkCall(call, info, p)
				}
			case *ast.AssignStmt:
				c.checkAssign(node.Lhs, node.Rhs, info, p)
			case *ast.GenDecl:
				for _, spec := range node.Specs {
					if vs, ok := spec.(*ast.ValueSpec); ok {
						c.checkAssign(vs.Names, vs.Values, info, p)
					}
				}
			case *ast.TypeAssertExpr:
				if !node.CommaOk && c.Asserts {
					c.report(node.X.Pos(), "", info, p)
				}
			}
			return true
		})
	}
}

// checkAssign checks an assignment or declaration for errors assigned to the
// blank identifier.
func (c *Checker) checkAssign(lhs, rhs []ast.Expr, info *types.Info, p *Package) {
	if len(rhs) == 0 {
		return
	}
	multi := len(lhs) != len(rhs)
	for i, l := range lhs {
		ident, ok := l.(*ast.Ident)
		if !ok || ident.Name != "_" {
			continue
		}
		var r ast.Expr
		if multi {
			r = rhs[0]
		} else {
			r = rhs[i]
		}
		if ta, ok := r.(*ast.TypeAssertExpr); ok && ta.CommaOk {
			if !c.Asserts {
				continue
			}
			if i != len(lhs)-1 {
				continue
			}
			if last, ok := lhs[len(lhs)-1].(*ast.Ident); ok && last.Name == "_" {
				c.report(ident.Pos(), "", info, p)
			}
			continue
		}
		if !c.Blank {
			continue
		}
		call, ok := r.(*ast.CallExpr)
		if !ok {
			continue
		}
		sig, _ := info.TypeOf(call.Fun).(*types.Signature)
		if sig == nil || sig.Results() == nil {
			continue
		}
		if i < sig.Results().Len() && isErrorType(sig.Results().At(i).Type()) {
			c.checkCall(call, info, p, ident.Pos())
		}
	}
}

// checkCall reports a call whose error result is silently discarded. If pos is
// not zero it overrides the position used for the report.
func (c *Checker) checkCall(call *ast.CallExpr, info *types.Info, p *Package, pos ...token.Pos) {
	sig, _ := info.TypeOf(call.Fun).(*types.Signature)
	if sig == nil || sig.Results() == nil {
		return
	}
	found := false
	for i := 0; i < sig.Results().Len(); i++ {
		if isErrorType(sig.Results().At(i).Type()) {
			found = true
			break
		}
	}
	if !found {
		return
	}
	fnName, calleeName, pkgPath := c.functionNames(call, info, p)
	if c.isExcluded(fnName, call, info) {
		return
	}
	if c.isIgnored(calleeName, pkgPath) {
		return
	}
	at := call.Lparen
	if len(pos) > 0 {
		at = pos[0]
	}
	c.report(at, fnName, info, p)
}

// functionNames computes the names used for exclusion matching and for the
// deprecated -ignore flag.
func (c *Checker) functionNames(call *ast.CallExpr, info *types.Info, p *Package) (fn, callee, pkgPath string) {
	switch fun := call.Fun.(type) {
	case *ast.SelectorExpr:
		obj := objectOf(info, fun)
		if obj == nil {
			return
		}
		callee = fun.Sel.Name
		if f, ok := obj.(*types.Func); ok {
			pkgPath = packagePath(obj, p)
			if sig, ok := f.Type().(*types.Signature); ok && sig.Recv() != nil {
				fn = "(" + receiverString(sig.Recv().Type()) + ")." + f.Name()
			} else if obj.Pkg() != nil {
				fn = obj.Pkg().Path() + "." + f.Name()
			}
		} else if obj.Pkg() != nil {
			pkgPath = obj.Pkg().Path()
		} else {
			pkgPath = p.PkgPath
		}
	case *ast.Ident:
		obj := info.Uses[fun]
		if obj == nil {
			obj = info.Defs[fun]
		}
		if obj == nil {
			return
		}
		callee = fun.Name
		pkgPath = packagePath(obj, p)
	}
	return
}

func objectOf(info *types.Info, sel *ast.SelectorExpr) types.Object {
	if s, ok := info.Selections[sel]; ok {
		return s.Obj()
	}
	return info.Uses[sel.Sel]
}

func packagePath(obj types.Object, p *Package) string {
	if obj.Pkg() != nil {
		return obj.Pkg().Path()
	}
	return p.PkgPath
}

// receiverString renders the receiver type of a method for exclusion matching.
func receiverString(t types.Type) string {
	switch t := t.(type) {
	case *types.Named:
		return t.String()
	case *types.Pointer:
		if _, ok := t.Elem().(*types.Named); ok {
			return t.String()
		}
	}
	return "interface"
}

func (c *Checker) isExcluded(fnName string, call *ast.CallExpr, info *types.Info) bool {
	if fnName == "" {
		return false
	}
	filters, ok := c.Excludes[fnName]
	if !ok {
		return false
	}
	if len(filters) == 0 {
		return true
	}
	if len(call.Args) == 0 {
		return false
	}
	arg := call.Args[0]
	if std, isStd := stdStream(arg, info); isStd {
		for _, f := range filters {
			if f == std {
				return true
			}
		}
		return false
	}
	t := info.TypeOf(arg)
	if t == nil {
		return false
	}
	s := t.String()
	for _, f := range filters {
		if f == s {
			return true
		}
	}
	return false
}

// stdStream reports whether the given expression is the literal os.Stdout or
// os.Stderr, and if so which one.
func stdStream(arg ast.Expr, info *types.Info) (string, bool) {
	sel, ok := arg.(*ast.SelectorExpr)
	if !ok {
		return "", false
	}
	if sel.Sel.Name != "Stdout" && sel.Sel.Name != "Stderr" {
		return "", false
	}
	obj := info.Uses[sel.Sel]
	if obj == nil {
		return "", false
	}
	if obj.Pkg() == nil || obj.Pkg().Path() != "os" {
		return "", false
	}
	return "os." + sel.Sel.Name, true
}

func (c *Checker) isIgnored(calleeName, pkgPath string) bool {
	if calleeName == "" {
		return false
	}
	for _, pkg := range []string{pkgPath, ""} {
		if re, ok := c.Ignore[pkg]; ok && re != nil && re.MatchString(calleeName) {
			return true
		}
	}
	return false
}

// report records an error at the given position.
func (c *Checker) report(pos token.Pos, fnName string, info *types.Info, p *Package) {
	position := c.fset.Position(pos)
	file := position.Filename
