// Checker checks Go packages for silently ignored errors.
type Checker struct {
	Abspath         bool
	Asserts         bool
	Blank           bool
	Excludes        excludeMap
	Ignore          ignoreList
	IgnoreGenerated bool
	IgnoreTests     bool
	Log             *log.Logger
	Mod             string
	Tags            tagList
	Verbose         bool

	fset   *token.FileSet
	Errors []reportedError
	seen   map[string]bool
	cwd    string
