var generatedRe = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

// Check loads the packages matching the given patterns and checks them.
func (c *Checker) Check(patterns []string) error {
	c.cwd, _ = os.Getwd()
	cfg := &Config{
		Tests:      !c.IgnoreTests,
		BuildFlags: buildFlags(c.Tags),
		Mod:        c.Mod,
	}
