	if fnName == "" {
		return false
	}
	filters, ok := c.Excludes[fnName]
	if !ok {
		return false
	}
	if len(filters) == 0 {
		return true
	}
	if len(call.Args) == 0 {
		return false
	}
	arg := call.Args[0]
	if std, isStd := stdStream(arg, info); isStd {
		for _, f := range filters {
