	if c.seen[key] {
		return
	}
	c.seen[key] = true
	line := ""
	if src, ok := p.Sources[position.Filename]; ok {
		lines := strings.Split(string(src), "\n")
		if position.Line-1 < len(lines) {
			line = strings.TrimSpace(lines[position.Line-1])
		}
	}
	c.Errors = append(c.Errors, reportedError{
		file: file,
		line: position.Line,
		col:  position.Column,
		text: line,
		fn:   fnName,
	})
}

// PrintErrors writes the found errors to w.
func (c *Checker) PrintErrors(w *os.File) {
	sort.Slice(c.Errors, func(i, j int) bool {
		if c.Errors[i].file != c.Errors[j].file {
			return c.Errors[i].file < c.Errors[j].file
		}
		if c.Errors[i].line != c.Errors[j].line {
			return c.Errors[i].line < c.Errors[j].line
		}
		return c.Errors[i].col < c.Errors[j].col
	})
	for _, e := range c.Errors {
		pos := fmt.Sprintf("%s:%d:%d", e.file, e.line, e.col)
		if e.fn != "" {
			fmt.Fprintf(w, "%s:\t%s\t%s\n", pos, e.fn, e.text)
		} else {
			fmt.Fprintf(w, "%s:\t%s\n", pos, e.text)
		}
	}
}

// isGeneratedFile reports whether the file contains a generated code comment.
func isGeneratedFile(file *ast.File) bool {
	for _, group := range file.Comments {
		for _, comment := range group.List {
			if generatedRe.MatchString(comment.Text) {
				return true
			}
		}
	}
	return false
}
