// Config holds the options for loading packages.
type Config struct {
	Tests      bool
	BuildFlags []string
	Mod        string
}

type listPackage struct {
	ImportPath string
	Name       string
	Dir        string
	GoFiles    []string
	DepOnly    bool
	ForTest    string
	Export     string
	ImportMap  map[string]string
	Imports    []string
	Error      *struct {
		ImportStack []string
		Pos         string
		Err         string
	}
}

// Load resolves the given patterns to packages and returns the root packages.
func Load(cfg *Config, patterns ...string) ([]*Package, error) {
	ld := newLoader(cfg)
	args := []string{"list", "-e", "-json", "-deps", "-export"}
	if cfg.Tests {
		args = append(args, "-test")
	}
	args = append(args, cfg.BuildFlags...)
	if cfg.Mod != "" {
		args = append(args, "-mod="+cfg.Mod)
	}
	args = append(args, "--")
	args = append(args, patterns...)

	stdout, stderr, err := goList(args...)
	if err != nil {
		if stdout == "" && (strings.Contains(stderr, "go.mod file not found") ||
			strings.Contains(stderr, "cannot find main module")) {
			return nil, nil
		}
		return nil, fmt.Errorf("err: %v: stderr: %s", err, stderr)
	}
	if err := ld.parseJSON(stdout); err != nil {
		return nil, err
	}
	var result []*Package
	for _, p := range ld.order {
		if !p.DepOnly {
			result = append(result, p)
		}
	}
	return result, nil
}

func goList(args ...string) (string, string, error) {
	cmd := exec.Command("go", args...)
	var out, errb strings.Builder
	cmd.Stdout = &out
	cmd.Stderr = &errb
	cerr := cmd.Run()
	return out.String(), errb.String(), cerr
}

type loader struct {
	fset    *token.FileSet
	cfg     *Config
	order   []*Package
	byID    map[string]*Package
	byPath  map[string]*Package
	byDir   map[string]*Package
	gcImp   types.Importer
	checked map[string]bool
	busy    map[string]bool
}

func newLoader(cfg *Config) *loader {
	return &loader{
		fset:    token.NewFileSet(),
		cfg:     cfg,
		byID:    map[string]*Package{},
		byPath:  map[string]*Package{},
		byDir:   map[string]*Package{},
		checked: map[string]bool{},
		busy:    map[string]bool{},
	}
}

func (ld *loader) parseJSON(data string) error {
	ld.gcImp = importer.ForCompiler(ld.fset, "gc", func(path string) (io.ReadCloser, error) {
		p, ok := ld.byPath[path]
		if !ok || p.Export == "" {
			return nil, fmt.Errorf("no export data for %s", path)
		}
		return os.Open(p.Export)
	})
	dec := json.NewDecoder(strings.NewReader(data))
	for {
		var lp listPackage
		if err := dec.Decode(&lp); err != nil {
			if err == io.EOF {
				break
			}
			return err
		}
		p := &Package{
			ID:        lp.ImportPath,
			PkgPath:   stripTestSuffix(lp.ImportPath),
			Name:      lp.Name,
			Dir:       lp.Dir,
			GoFiles:   absPaths(lp.Dir, lp.GoFiles),
			fset:      ld.fset,
			ImportMap: lp.ImportMap,
			Export:    lp.Export,
			DepOnly:   lp.DepOnly,
		}
		if lp.Error != nil {
			pos := lp.Error.Pos
			if pos == "" {
				pos = "-"
			}
			p.Errors = append(p.Errors, Error{Pos: pos, Msg: strings.TrimSpace(lp.Error.Err)})
		}
		ld.order = append(ld.order, p)
		if _, ok := ld.byID[p.ID]; !ok {
			ld.byID[p.ID] = p
		}
		if _, ok := ld.byPath[p.PkgPath]; !ok {
			ld.byPath[p.PkgPath] = p
		}
		if p.Dir != "" {
			if _, ok := ld.byDir[p.Dir]; !ok {
				ld.byDir[p.Dir] = p
			}
		}
	}
	return nil
}

func stripTestSuffix(id string) string {
	if i := strings.Index(id, " ["); i >= 0 {
		return id[:i]
	}
	return id
}

func absPaths(dir string, files []string) []string {
	var out []string
	for _, f := range files {
		if filepath.IsAbs(f) {
			out = append(out, f)
			continue
		}
		out = append(out, filepath.Join(dir, f))
	}
	return out
}

// imp resolves imports for the package currently being type checked.
type imp struct {
	ld   *loader
	from *Package
}

func (i *imp) Import(path string) (*types.Package, error) {
	return i.ImportFrom(path, i.from.Dir, 0)
}

func (i *imp) ImportFrom(path, dir string, mode types.ImportMode) (*types.Package, error) {
	if from := i.ld.byDir[dir]; from != nil {
		i.from = from
	}
	resolved := path
	if i.from != nil && i.from.ImportMap != nil {
		if r, ok := i.from.ImportMap[path]; ok {
			resolved = r
		}
	}
	target, ok := i.ld.byID[resolved]
	if !ok {
		target, ok = i.ld.byPath[resolved]
	}
	if !ok {
		return types.NewPackage(resolved, ""), nil
	}
	if target.Types != nil {
		return target.Types, nil
	}
	if target.Export != "" {
		return i.ld.gcImp.Import(resolved)
	}
	if err := loadPackage(target); err != nil {
		return nil, err
	}
	if target.Types != nil {
		return target.Types, nil
	}
	return types.NewPackage(resolved, ""), nil
}

// loadPackage parses and type checks the given package, recording any errors
// that are found.
func loadPackage(p *Package) error {
	if p.loaded {
		return nil
	}
	p.loaded = true
	fset := p.fset
	info := &types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
		Implicits:  map[ast.Node]types.Object{},
		Instances:  map[*ast.Ident]types.Instance{},
		Scopes:     map[ast.Node]*types.Scope{},
	}
	p.TypesInfo = info
	p.Sources = map[string][]byte{}
	var files []*ast.File
	for _, f := range p.GoFiles {
		data, err := os.ReadFile(f)
		if err != nil {
			p.Errors = append(p.Errors, Error{Pos: f + ":1", Msg: err.Error()})
			continue
		}
		p.Sources[f] = data
		file, err := parser.ParseFile(fset, f, data, parser.ParseComments)
		if err != nil {
			if el, ok := err.(scanner.ErrorList); ok {
				for _, e := range el {
					p.Errors = append(p.Errors, Error{Pos: e.Pos.String(), Msg: e.Msg})
				}
			} else {
				p.Errors = append(p.Errors, Error{Pos: f, Msg: err.Error()})
			}
		}
		if file != nil {
			files = append(files, file)
		}
	}
	p.Syntax = files

	conf := types.Config{
		Importer: &imp{ld: theLoader, from: p},
		Error: func(err error) {
			if te, ok := err.(types.Error); ok {
				p.Errors = append(p.Errors, Error{
					Pos: te.Fset.Position(te.Pos).String(),
					Msg: fixUnusedVarMessage(te.Msg),
				})
			}
		},
	}
	pkg, _ := conf.Check(p.PkgPath, fset, files, info)
	p.Types = pkg
	return nil
}

// theLoader is set by Load so that the importer can access the loaded packages.
var theLoader *loader
