package main

import (
	"go/types"
	"strings"
)

var errType = types.Universe.Lookup("error").Type()
var errIface = errType.Underlying().(*types.Interface)

// isErrorType reports whether the given type is the error interface, a named
// type that implements it, or a pointer to such a named type.
func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	if named, ok := t.(*types.Named); ok {
		if obj := named.Obj(); obj != nil && obj.Pkg() == nil && obj.Name() == "error" {
			return true
		}
		return types.Implements(named, errIface)
	}
	if ptr, ok := t.(*types.Pointer); ok {
		return types.Implements(ptr, errIface)
	}
	return false
}

// fixUnusedVarMessage rewrites the go/types message for an unused variable to
// the form used by newer Go releases.
func fixUnusedVarMessage(msg string) string {
	if i := strings.LastIndex(msg, " declared and not used"); i >= 0 {
		return "declared and not used: " + msg[:i]
	}
	return msg
}
