{"command": "cd /tmp/impl && cat > main.go <<'GOEOF'
package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"regexp"
	"strings"
)

var ignoreFlags = ignoreList{}
var tagFlagList tagList

func main() {
	log.SetFlags(0)

	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	var (
		abspathFlag     = fs.Bool("abspath", false, "print absolute paths to files")
		assertsFlag     = fs.Bool("asserts", false, "if true, check for ignored type assertion results")
		blankFlag       = fs.Bool("blank", false, "if true, check for errors assigned to blank identifier")
		excludeFlag     = fs.String("exclude", "", "Path to a file containing a list of functions to exclude from checking")
		excludeOnlyFlag = fs.Bool("excludeonly", false, "Use only excludes from -exclude file")
		ignoreGenFlag   = fs.Bool("ignoregenerated", false, "if true, checking of files with generated code is disabled")
		ignorePkgFlag   = fs.String("ignorepkg", "", "comma-separated list of package paths to ignore")
		ignoreTestsFlag = fs.Bool("ignoretests", false, "if true, checking of _test.go files is disabled")
		modFlag         = fs.String("mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
		verboseFlag     = fs.Bool("verbose", false, "produce more verbose logging")
	)
	fs.Var(&ignoreFlags, "ignore", `[deprecated] comma-separated list of pairs of the form pkg:regex
            the regex is used to ignore names within pkg.`)
	fs.Var(&tagFlagList, "tags", "comma or space-separated list of build tags to include")
	if err := fs.Parse(os.Args[1:]); err != nil {
		os.Exit(2)
	}

	excludes := excludeMap{}
	if *excludeFlag != "" {
		var err error
		excludes, err = loadExcludeFile(*excludeFlag)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(2)
		}
	}
	if !*excludeOnlyFlag {
		for name, types := range defaultExcludes {
			excludes[name] = types
		}
	}
	for _, pkg := range splitList(*ignorePkgFlag) {
		ignoreFlags[pkg] = regexp.MustCompile(".*")
	}

	checker := &Checker{
		Abspath:         *abspathFlag,
		Asserts:         *assertsFlag,
		Blank:           *blankFlag,
		Excludes:        excludes,
		Ignore:          ignoreFlags,
		IgnoreGenerated: *ignoreGenFlag,
		IgnoreTests:     *ignoreTestsFlag,
		Log:             log.New(os.Stderr, "", 0),
		Mod:             *modFlag,
		Tags:            tagFlagList,
		Verbose:         *verboseFlag,
	}

	if err := checker.Check(fs.Args()); err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}
	if len(checker.Errors) > 0 {
		checker.PrintErrors(os.Stdout)
		os.Exit(1)
	}
}

func splitList(s string) []string {
	var out []string
	for _, part := range strings.Split(s, ",") {
		if part == "" {
			continue
		}
		out = append(out, part)
