package main

import (
	"regexp"
	"strings"
)

// ignoreList implements flag.Value for the deprecated -ignore flag. It maps a
// package path (or the empty string, meaning all packages) to a regular
// expression matching the names to ignore within that package.
type ignoreList map[string]*regexp.Regexp

func (f ignoreList) String() string {
	if f == nil {
		return ""
	}
	var parts []string
	for pkg, re := range f {
		parts = append(parts, pkg+":"+re.String())
	}
	return strings.Join(parts, ",")
}

func (f ignoreList) Set(value string) error {
	if value == "" {
		return nil
	}
	for _, entry := range strings.Split(value, ",") {
		pkg := ""
		re := entry
		if i := strings.Index(entry, ":"); i >= 0 {
			pkg = entry[:i]
			re = entry[i+1:]
		}
		regex, err := regexp.Compile(re)
		if err != nil {
			return err
		}
		f[pkg] = regex
	}
	return nil
}

// tagList implements flag.Value for the -tags flag, which accepts a
// comma- or space-separated list of build tags.
type tagList []string

func (t tagList) String() string {
	if t == nil {
		return ""
	}
	return strings.Join(t, " ")
}

func (t *tagList) Set(value string) error {
	if value == "" {
		return nil
	}
	for _, field := range strings.FieldsFunc(value, func(r rune) bool {
		return r == ',' || r == ' '
	}) {
		*t = append(*t, field)
	}
	return nil
}
GOEOF
