package main

import (
	"encoding/json"
	"fmt"
	"go/importer"
	"go/token"
	"go/types"
	"io"
	"os"
	"os/exec"
	"strings"
)

type Pkg struct {
	ImportPath string
	Export     string
}

func main() {
	out, _ := exec.Command("go", "list", "-e", "-export", "-json", "hash").CombinedOutput()
	m := map[string]string{}
	dec := json.NewDecoder(strings.NewReader(string(out)))
	for {
		var p Pkg
		if err := dec.Decode(&p); err != nil {
			break
		}
		m[p.ImportPath] = p.Export
	}
	fset := token.NewFileSet()
	imp := importer.ForCompiler(fset, "gc", func(path string) (io.ReadCloser, error) {
		f, ok := m[path]
		if !ok {
			return nil, fmt.Errorf("no export for %s", path)
		}
		return os.Open(f)
	})
	pkg, err := imp.Import("hash")
	if err != nil {
		fmt.Println("err:", err)
		return
	}
	obj := pkg.Scope().Lookup("Hash")
	nt := obj.Type().(*types.Named)
	ifc := nt.Underlying().(*types.Interface)
	for i := 0; i < ifc.NumMethods(); i++ {
		meth := ifc.Method(i)
		sig := meth.Type().(*types.Signature)
		fmt.Printf("method %s pkg=%v recv=%v recvNil=%v\n", meth.Name(), meth.Pkg(), sig.Recv(), sig.Recv() == nil)
	}
	ms := types.NewMethodSet(nt)
	for i := 0; i < ms.Len(); i++ {
		sel := ms.At(i)
		f, _ := sel.Obj().(*types.Func)
		sig := f.Type().(*types.Signature)
		fmt.Printf("mset %s recv=%v\n", f.Name(), sig.Recv())
	}
}
EOF
